780	    const modelingGridMeshes = [gridSubFine, gridSubMain, gridDecade, modelingGridAxisX, modelingGridAxisZ];
781	    const modelingGrid = [...modelingGridMeshes, ...modelingGridLabels.map((l) => l.mesh)];
782	
783	    // Formate une graduation sans zéros parasites (250, 25, 2.5, 0.25 …).
784	    const formatGridValue = (v: number) => String(Number(v.toPrecision(6)));
785	
786	    /**
787	     * Choix du pas `S` : on le veut compris entre `GRID_MIN_PX` et 10×`GRID_MIN_PX` pixels à
788	     * l'écran, ce qui revient à subdiviser dès que la grille « prend toute la place ». Le
789	     * niveau fin (pas S/10) apparaît en fondu au fur et à mesure qu'il atteint lui aussi cette
790	     * taille lisible ; quand il y arrive tout à fait, `S` descend d'une décade et ce niveau
791	     * fin devient le niveau principal — au même pas, donc sans qu'aucun trait ne se déplace.
792	     */
793	    const GRID_MIN_PX = 10;
794	    // Demi-étendue visée à l'entrée du mode modélisation, en mm : cadre une dizaine de
795	    // graduations de part et d'autre de l'origine, le pas restant à 10 mm.
796	    const GRID_DEFAULT_HALF_EXTENT_MM = 90;
797	    let gridStepScale = 0; // 0 = jamais appliqué, force le premier passage
798	    const updateGrid = (worldPerPixel: number) => {
799	      const l = Math.log10(GRID_MIN_PX * worldPerPixel);
800	      const exponent = Math.ceil(l);
801	      const step = Math.pow(10, exponent);
802	      // `fade` ∈ [0,1) : 0 quand le niveau fin serait trop dense, 1 juste avant qu'il ne
803	      // devienne le niveau principal. Lissé pour que l'apparition ne soit pas linéaire.
804	      const t = exponent - l;
805	      const fade = t * t * (3 - 2 * t);
806	
807	      if (gridSubFine.material) gridSubFine.material.alpha = fade * GRID_ALPHA_MINOR;
808	      gridSubFine.setEnabled(fade > 0.02);
809	
810	      if (step === gridStepScale) return;
811	      gridStepScale = step;
812	
813	      gridSubFine.scaling.setAll(step / 10);
814	      gridSubMain.scaling.setAll(step);
815	      gridDecade.scaling.setAll(step);
816	      modelingGridAxisX.scaling.setAll(step);
817	      modelingGridAxisZ.scaling.setAll(step);
818	      modelingGridLabels.forEach(({ mesh, tileValue, tilePosition }) => {
819	        mesh.scaling.setAll(step);
820	        mesh.position.copyFrom(tilePosition).scaleInPlace(step);
821	        mesh.material = getGridLabelMaterial(formatGridValue(tileValue * step));
822	      });
823	    };
824	
825	    // Empêche de « passer au travers » du plan de travail en zoomant : au lieu de traverser,
826	    // la grille se subdivise et la caméra reste à distance de sa cible.
827	    camera.lowerRadiusLimit = 0.5;
828	    camera.upperRadiusLimit = 100000;
829	
830	    /**
831	     * Barre d'échelle du mode modélisation. Pour une caméra en perspective, un pixel au niveau
832	     * de la cible vaut `2·radius·tan(fov/2) / hauteurRendu` unités monde. On choisit une
833	     * longueur « ronde » (1, 2 ou 5 × 10ⁿ) proche de `SCALE_BAR_TARGET_PX`, puis on en déduit
834	     * la largeur réelle de la barre — c'est la barre qui s'ajuste au chiffre, pas l'inverse.
835	     */
836	    const SCALE_BAR_TARGET_PX = 140;
837	    const formatDistance = (mm: number) => {
838	      if (mm >= 1000) return `${formatGridValue(mm / 1000)} m`;
839	      if (mm >= 10) return `${formatGridValue(mm / 10)} cm`;
840	      return `${formatGridValue(mm)} mm`;
841	    };
842	    const niceLength = (raw: number) => {
843	      const exp = Math.floor(Math.log10(raw));
844	      const pow = Math.pow(10, exp);
845	      const mantissa = raw / pow;
846	      const snapped = mantissa >= 5 ? 5 : mantissa >= 2 ? 2 : 1;
847	      return snapped * pow;
848	    };
849	
850	    let modelingActive = false;
851	    let lastScaleBarLabel = '';
852	    let lastScaleBarPx = 0;
853	    const gridZoomObserver = scene.onBeforeRenderObservable.add(() => {
854	      if (!modelingActive) return;
855	
856	      const worldPerPixel = (2 * camera.radius * Math.tan(camera.fov / 2)) / engine.getRenderHeight();
857	      if (!Number.isFinite(worldPerPixel) || worldPerPixel <= 0) return;
858	
859	      updateGrid(worldPerPixel);
860	      orientGridLabels();
861	
862	      const length = niceLength(SCALE_BAR_TARGET_PX * worldPerPixel);
863	      const label = formatDistance(length);
864	      const px = Math.round(length / worldPerPixel);
865	      // Suivre `px` et pas seulement le libellé : entre deux changements d'unité la largeur
866	      // varie continûment avec le zoom, et ne la réappliquer qu'au changement de libellé
867	      // laisserait la barre figée alors que la distance qu'elle représente a bougé.
868	      if (label !== lastScaleBarLabel || px !== lastScaleBarPx) {
869	        lastScaleBarLabel = label;
870	        lastScaleBarPx = px;
871	        setScaleBar({ px, label });
872	      }
873	    });
874	
875	    // Bascule slicer ↔ modélisation : on échange le volume d'impression contre la grille
876	    // d'esquisse et on relâche toute sélection/gizmo hérité de l'autre mode.
877	    const onModeChanged = (e: Event) => {
878	      const { mode } = (e as CustomEvent<{ mode: 'slicer' | 'modeling' }>).detail;
879	      if (scene.isDisposed) return;
880	
881	      const modeling = mode === 'modeling';
882	      modelingActive = modeling;
883	      volumeRoot.setEnabled(!modeling);
884	      // Entrer en modélisation sur un cadrage fixe plutôt que d'hériter du zoom du slicer, qui
885	      // donnerait une graduation arbitraire et pouvait laisser les étiquettes hors champ.
886	      // `radius = demi-étendue / tan(fov/2)` est l'inverse exact de la demi-hauteur visible à
887	      // la distance de la cible ; le pas de 10 mm en découle via `updateGrid`.
888	      if (modeling) {
889	        // La cible héritée du slicer est à mi-hauteur du volume d'impression ; la grille, elle,
890	        // est au sol. Sans ce recentrage le cadrage viserait au-dessus du plan de travail.
891	        camera.setTarget(BABYLON.Vector3.Zero());
892	        camera.radius = GRID_DEFAULT_HALF_EXTENT_MM / Math.tan(camera.fov / 2);
893	        // Vue de trois quarts plongeante : à beta rasant la grille est vue par la tranche et
894	        // les étiquettes, couchées dans son plan, deviennent illisibles.
895	        camera.beta = Math.min(camera.beta, 0.9);
896	        const worldPerPixel = (2 * camera.radius * Math.tan(camera.fov / 2)) / engine.getRenderHeight();
897	        // `gridStepScale` survit à la sortie du mode : sans cette remise à zéro, rentrer à
898	        // nouveau sur le même pas ferait sortir `updateGrid` par son court-circuit et les
899	        // étiquettes resteraient sans matériau ni position, donc invisibles.
900	        gridStepScale = 0;
901	        updateGrid(worldPerPixel);
902	      }
903	      modelingGrid.forEach((g) => g.setEnabled(modeling));
904	
905	      if (!modeling) {
906	        lastScaleBarLabel = '';
907	        lastScaleBarPx = 0;
908	        setScaleBar(null);
909	      } else if (gridSubFine.material && gridSubFine.material.alpha <= 0.02) {
910	        gridSubFine.setEnabled(false); // le niveau fin reste masqué tant qu'il est trop dense
911	      }
912	
913	      if (modeling) {
914	        gizmoManager.positionGizmoEnabled = false;
915	        gizmoManager.rotationGizmoEnabled = false;
