/**
 * Fait « suivre » le pavage fini (±`GRID_TILE_EXTENT` tuiles) sous la cible caméra, pour
 * qu'il paraisse infini au lieu de rester cloué à l'origine monde : sans ça, son étendue en
 * unités monde (`±GRID_TILE_EXTENT · step`) rétrécit avec le zoom et finit par ne plus
 * couvrir l'endroit visé si on n'est pas au centre.
 *
 * Les trois niveaux partagent TOUJOURS le même décalage (`gridAnchorX/Z`) : leur motif est
 * bâti sur la même tuile de base (`gridTileSub`/`gridTileDecade`), donc les désynchroniser
 * romprait leur imbrication (le fin ne tomberait plus pile sous le principal). Cet ancrage
 * n'est recalculé que quand la cible s'éloigne trop de la fenêtre déjà couverte — jamais à
 * chaque frame — pour ne jamais interférer avec le zoom : à ancrage inchangé, la mise à
 * l'échelle seule garantit déjà qu'aucun trait ne bouge (les indices d'une décade sont un
 * sous-multiple exact de ceux de la décade voisine, quel que soit le décalage appliqué aux
 * deux). Le pas de la grille étant toujours une puissance de 10, `10·step` (le plus grand
 * commun repeat des trois niveaux, cf. `gridTileDecade`) est un choix d'ancrage valide à
 * n'importe quelle échelle.
 */
const GRID_RECENTER_MARGIN_TILES = 40; // marge (en tuiles) avant de redécouper la fenêtre
let gridAnchorX = 0;
let gridAnchorZ = 0;
const recenterPeriodicGrid = () => {
  if (gridStepScale <= 0) return;
  const margin = GRID_RECENTER_MARGIN_TILES * gridStepScale;
  if (Math.abs(camera.target.x - gridAnchorX) <= margin && Math.abs(camera.target.z - gridAnchorZ) <= margin) {
    return;
  }
  const period = gridStepScale * 10;
  gridAnchorX = Math.round(camera.target.x / period) * period;
  gridAnchorZ = Math.round(camera.target.z / period) * period;
  gridSubFine.position.set(gridAnchorX, 0, gridAnchorZ);
  gridSubMain.position.set(gridAnchorX, 0, gridAnchorZ);
  gridDecade.position.set(gridAnchorX, 0, gridAnchorZ);
};

