const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: 'new',
    args: [
      '--no-sandbox',
      '--use-gl=swiftshader',
      '--enable-webgl',
      '--ignore-gpu-blocklist',
      '--window-size=1400,900',
    ],
    defaultViewport: { width: 1400, height: 900 },
  });
  const page = await browser.newPage();
  const logs = [];
  page.on('console', (msg) => logs.push(`[console:${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => logs.push(`[pageerror] ${err.message}`));

  await page.goto('http://localhost:8080/', { waitUntil: 'networkidle0', timeout: 30000 });
  await new Promise((r) => setTimeout(r, 1500));
  await page.screenshot({ path: 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/e6ba8ae5-7493-49bb-87e9-cfdb4998cd80/scratchpad/pw/01-initial.png' });

  console.log('--- initial logs ---');
  console.log(logs.join('\n'));
  console.log('--- title ---', await page.title());

  // Dump visible text buttons/labels to find the "Modélisation" tab selector.
  const texts = await page.$$eval('button, [role="tab"], a, div', (els) =>
    els
      .map((e) => (e.textContent || '').trim())
      .filter((t) => t && t.length < 40)
  );
  console.log('--- candidate texts (unique, truncated) ---');
  console.log([...new Set(texts)].slice(0, 200).join(' | '));

  await browser.disconnect();
})().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

