const puppeteer = require('puppeteer-core');
const path = require('path');

const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const OUT = 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/e6ba8ae5-7493-49bb-87e9-cfdb4998cd80/scratchpad/pw';
const PROFILE = path.join(OUT, 'isolated-profile');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: 'new',
    userDataDir: PROFILE,
    args: [
      '--no-sandbox',
      '--use-gl=swiftshader',
      '--enable-webgl',
      '--ignore-gpu-blocklist',
      '--window-size=1400,900',
      '--no-first-run',
      '--no-default-browser-check',
    ],
    defaultViewport: { width: 1400, height: 900 },
  });

  try {
    const page = await browser.newPage();
    const logs = [];
    page.on('console', (msg) => logs.push(`[console:${msg.type()}] ${msg.text()}`));
    page.on('pageerror', (err) => logs.push(`[pageerror] ${err.message}`));

    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 2500));

    // Click the "Modélisation" tab.
    const clicked = await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll('button, [role="tab"], a'));
      const el = els.find((e) => (e.textContent || '').trim() === 'Modélisation');
      if (el) { el.click(); return true; }
      return false;
    });
    console.log('=== clicked Modélisation tab:', clicked);
    await new Promise((r) => setTimeout(r, 1500));
    await page.screenshot({ path: path.join(OUT, '02-modeling.png') });

    const canvas = await page.$('#babylon-canvas');
    const box = await canvas.boundingBox();
    console.log('=== canvas box:', box);
    const cx = box.x + box.width / 2;
    const cy = box.y + box.height / 2;

    // Helper to count context-menu-like fixed overlays present in DOM (our menu renders at
    // position:fixed with a high z-index once `contextMenu` state is set).
    const countHighZFixed = async () => page.evaluate(() => {
      return Array.from(document.querySelectorAll('div')).filter((d) => {
        const s = getComputedStyle(d);
        return s.position === 'fixed' && parseInt(s.zIndex || '0', 10) >= 999;
      }).length;
    });

    console.log('--- before any right click, fixed-high-z divs:', await countHighZFixed());

    // 1) Plain right click (no movement) -> menu SHOULD appear.
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'right' });
    await page.mouse.up({ button: 'right' });
    await new Promise((r) => setTimeout(r, 400));
    await page.screenshot({ path: path.join(OUT, '03-after-plain-right-click.png') });
    console.log('--- after plain right click, fixed-high-z divs:', await countHighZFixed());

    // Close it if open (click elsewhere) before next test.
    await page.mouse.click(50, 50, { button: 'left' });
    await new Promise((r) => setTimeout(r, 300));

    // 2) Right click DRAG (mousedown, move far, mouseup) -> menu should NOT appear.
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'right' });
    await page.mouse.move(cx + 120, cy + 80, { steps: 15 });
    await page.mouse.up({ button: 'right' });
    await new Promise((r) => setTimeout(r, 400));
    await page.screenshot({ path: path.join(OUT, '04-after-drag-right-click.png') });
    console.log('--- after drag right click, fixed-high-z divs:', await countHighZFixed());

    console.log('=== logs ===');
    console.log(logs.join('\n'));
  } finally {
    await browser.close();
  }
})().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

