const puppeteer = require('puppeteer-core');
const path = require('path');

const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const OUT = 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/e6ba8ae5-7493-49bb-87e9-cfdb4998cd80/scratchpad/pw';
const PROFILE = path.join(OUT, 'isolated-profile');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: 'new',
    userDataDir: PROFILE,
    args: [
      '--no-sandbox', '--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist',
      '--window-size=1400,900', '--no-first-run', '--no-default-browser-check',
    ],
    defaultViewport: { width: 1400, height: 900 },
  });

  try {
    const page = await browser.newPage();
    const logs = [];
    page.on('console', (msg) => logs.push(`[console:${msg.type()}] ${msg.text()}`));
    page.on('pageerror', (err) => logs.push(`[pageerror] ${err.message}`));

    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 2500));

    await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll('button, [role="tab"], a'));
      const el = els.find((e) => (e.textContent || '').trim() === 'Modélisation');
      if (el) el.click();
    });
    await new Promise((r) => setTimeout(r, 1200));

    // Instrument at document level (capture phase = fires first, before canvas listeners can
    // stop it from bubbling further) to see exactly what happens for each raw event.
    await page.evaluate(() => {
      window.__evlog = [];
      for (const type of ['pointerdown', 'pointerup', 'mousedown', 'mouseup', 'contextmenu']) {
        document.addEventListener(type, (e) => {
          window.__evlog.push(`${type} button=${e.button} defaultPrevented=${e.defaultPrevented} target=${e.target.id || e.target.tagName}`);
        }, true); // capture phase: runs before any canvas-level bubble-order listener could stop propagation to us
      }
    });

    const canvas = await page.$('#babylon-canvas');
    const box = await canvas.boundingBox();
    const cx = box.x + box.width / 2;
    const cy = box.y + box.height / 2;

    console.log('=== TEST A: plain right click ===');
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'right' });
    await page.mouse.up({ button: 'right' });
    await new Promise((r) => setTimeout(r, 300));
    console.log(await page.evaluate(() => window.__evlog.join('\n')));
    await page.evaluate(() => { window.__evlog.length = 0; });

    // Check whether our React contextMenu state actually opened (look for the menu's item text).
    const menuVisibleA = await page.evaluate(() =>
      !!Array.from(document.querySelectorAll('div')).find((d) => d.textContent && d.textContent.includes('Supprimer'))
    );
    console.log('menu visible after plain right click:', menuVisibleA);
    await page.screenshot({ path: path.join(OUT, '05-plain.png') });

    await page.mouse.click(50, 50, { button: 'left' });
    await new Promise((r) => setTimeout(r, 300));
    await page.evaluate(() => { window.__evlog.length = 0; });

    console.log('=== TEST B: right click drag ===');
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'right' });
    await page.mouse.move(cx + 150, cy + 100, { steps: 20 });
    await page.mouse.up({ button: 'right' });
    await new Promise((r) => setTimeout(r, 300));
    console.log(await page.evaluate(() => window.__evlog.join('\n')));
    const menuVisibleB = await page.evaluate(() =>
      !!Array.from(document.querySelectorAll('div')).find((d) => d.textContent && d.textContent.includes('Supprimer'))
    );
    console.log('menu visible after drag right click:', menuVisibleB);
    await page.screenshot({ path: path.join(OUT, '06-drag.png') });

    console.log('=== console/page logs ===');
    console.log(logs.join('\n'));
  } finally {
    await browser.close();
  }
})().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

