const puppeteer = require('puppeteer-core');
const path = require('path');

const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const OUT = 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/e6ba8ae5-7493-49bb-87e9-cfdb4998cd80/scratchpad/pw';
const PROFILE = path.join(OUT, 'isolated-profile');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: 'new',
    userDataDir: PROFILE,
    args: [
      '--no-sandbox', '--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist',
      '--window-size=1400,900', '--no-first-run', '--no-default-browser-check',
    ],
    defaultViewport: { width: 1400, height: 900 },
  });

  try {
    const page = await browser.newPage();
    page.on('pageerror', (err) => console.log('[pageerror]', err.message));

    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 2500));
    await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll('button, [role="tab"], a'));
      const el = els.find((e) => (e.textContent || '').trim() === 'Modélisation');
      if (el) el.click();
    });
    await new Promise((r) => setTimeout(r, 1200));

    const canvas = await page.$('#babylon-canvas');
    const box = await canvas.boundingBox();
    const cx = box.x + box.width / 2;
    const cy = box.y + box.height / 2;

    console.log('debug before anything:', await page.evaluate(() => window.__debugGrid && window.__debugGrid()));

    // Zoom in a lot first (wheel scroll = zoom for ArcRotateCamera).
    await page.mouse.move(cx, cy);
    for (let i = 0; i < 25; i++) {
      await page.mouse.wheel({ deltaY: -120 });
      await new Promise((r) => setTimeout(r, 20));
    }
    await new Promise((r) => setTimeout(r, 300));
    console.log('debug after zoom-in:', await page.evaluate(() => window.__debugGrid()));
    await page.screenshot({ path: path.join(OUT, '10-zoomed-center.png') });

    // Now pan with RIGHT-button drag, repeated several times to accumulate a large offset.
    for (let i = 0; i < 6; i++) {
      await page.mouse.move(cx, cy);
      await page.mouse.down({ button: 'right' });
      await page.mouse.move(cx - 300, cy - 200, { steps: 10 });
      await page.mouse.up({ button: 'right' });
      await new Promise((r) => setTimeout(r, 100));
    }
    await new Promise((r) => setTimeout(r, 300));
    console.log('debug after right-drag pan x6:', await page.evaluate(() => window.__debugGrid()));
    await page.screenshot({ path: path.join(OUT, '11-after-pan.png') });

    // Try ALSO left-drag (in case right button doesn't pan in this app - maybe it's ctrl+left or middle).
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'left' });
    await page.mouse.move(cx - 200, cy - 150, { steps: 10 });
    await page.mouse.up({ button: 'left' });
    await new Promise((r) => setTimeout(r, 300));
    console.log('debug after left-drag:', await page.evaluate(() => window.__debugGrid()));
    await page.screenshot({ path: path.join(OUT, '12-after-leftdrag.png') });

    // Middle-button drag too.
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'middle' });
    await page.mouse.move(cx - 300, cy - 200, { steps: 10 });
    await page.mouse.up({ button: 'middle' });
    await new Promise((r) => setTimeout(r, 300));
    console.log('debug after middle-drag:', await page.evaluate(() => window.__debugGrid()));
    await page.screenshot({ path: path.join(OUT, '13-after-middledrag.png') });
  } finally {
    await browser.close();
  }
})().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

