1717	    // d'origine de Fusion 360, jamais jointifs) et évite le z-fighting sur les arêtes.
1718	    const SKETCH_PLANE_GAP = 4;
1719	
1720	    // Même effet « verre dépoli » que le plateau (`glassDiscMat` défini plus haut) : le
1721	    // fragment shader échantillonne `blurRT` en coordonnées ÉCRAN (pas UV du mesh), donc il
1722	    // est réutilisable tel quel sur n'importe quelle géométrie/orientation — on y ajoute
1723	    // simplement une teinte réglable en uniforme pour distinguer l'état survolé du défaut,
1724	    // ce qu'un ShaderMaterial partagé ne permettrait pas sans ce paramètre.
1725	    BABYLON.Effect.ShadersStore["sketchPlaneGlassVertexShader"] = `
1726	      precision highp float;
1727	      attribute vec3 position;
1728	      uniform mat4 worldViewProjection;
1729	      varying vec4 vClip;
1730	      void main(void) {
1731	        vec4 outPosition = worldViewProjection * vec4(position, 1.0);
1732	        gl_Position = outPosition;
1733	        vClip = outPosition;
1734	      }
1735	    `;
1736	    BABYLON.Effect.ShadersStore["sketchPlaneGlassFragmentShader"] = `
1737	      precision highp float;
1738	      varying vec4 vClip;
1739	      uniform sampler2D blurTex;
1740	      uniform vec4 tintColor;
1741	      void main(void) {
1742	        vec2 ndc = vClip.xy / vClip.w;
1743	        vec2 uv = ndc * 0.5 + 0.5;
1744	        vec3 blurred = texture2D(blurTex, uv).rgb;
1745	        vec3 finalColor = mix(blurred, tintColor.rgb, tintColor.a);
1746	        gl_FragColor = vec4(finalColor, 1.0);
1747	      }
1748	    `;
1749	    const makeSketchPlaneGlassMat = (name: string, tint: BABYLON.Color4): BABYLON.ShaderMaterial => {
1750	      const mat = new BABYLON.ShaderMaterial(name, scene, { vertex: "sketchPlaneGlass", fragment: "sketchPlaneGlass" }, {
1751	        attributes: ["position"],
1752	        uniforms: ["worldViewProjection", "tintColor"],
1753	        samplers: ["blurTex"],
1754	      });
1755	      mat.setTexture("blurTex", blurRT);
1756	      mat.setColor4("tintColor", tint);
1757	      mat.backFaceCulling = false;
1758	      return mat;
1759	    };
1760	
1761	    // Teinte neutre bleu-gris par défaut, cyan (l'accent déjà utilisé partout dans l'app) au
1762	    // survol — la 4e composante est la force du mélange avec l'arrière-plan flouté.
1763	    const sketchPlaneDefaultMat = makeSketchPlaneGlassMat("sketchPlaneDefaultMat", new BABYLON.Color4(0.55, 0.68, 0.78, 0.4));
1764	    const sketchPlaneHoverMat = makeSketchPlaneGlassMat("sketchPlaneHoverMat", new BABYLON.Color4(0, 0.94, 1, 0.55));
1765	
1766	    /**
1767	     * Un plan d'origine Fusion 360 est un quadrant partant de l'origine, pas un carré centré
1768	     * dessus : les 3 plaques regardent vers le même coin sans jamais s'y toucher. `CreatePlane`
1769	     * centre son carré sur son origine locale ; on le redécale donc de (gap + moitié) sur ses
1770	     * deux axes locaux AVANT rotation, puis on fait tourner ce décalage par la même rotation
1771	     * pour obtenir la bonne position monde — cette approche matricielle évite de devoir déduire
1772	     * à la main, pour chaque axe, dans quel sens la rotation renvoie le coin (erreurs de signe).
1773	     * On garde la matrice de rotation : elle sert aussi à placer les arêtes pointillées.
1774	     */
1775	    const sketchPlateRotMatrix = new Map<BABYLON.Mesh, BABYLON.Matrix>();
1776	    const makeSketchPlanePlate = (name: string, rotation: BABYLON.Vector3): BABYLON.Mesh => {
1777	      const plate = BABYLON.MeshBuilder.CreatePlane(
1778	        name, { size: SKETCH_PLANE_SIZE, sideOrientation: BABYLON.Mesh.DOUBLESIDE }, scene,
1779	      );
1780	      plate.rotation = rotation;
1781	      const rotMatrix = BABYLON.Matrix.RotationYawPitchRoll(rotation.y, rotation.x, rotation.z);
1782	      const inset = SKETCH_PLANE_GAP + SKETCH_PLANE_SIZE / 2;
1783	      plate.position = BABYLON.Vector3.TransformNormal(new BABYLON.Vector3(inset, inset, 0), rotMatrix);
1784	      plate.material = sketchPlaneDefaultMat;
1785	      plate.isPickable = false; // activée seulement pendant la sélection de plan
1786	      plate.setEnabled(false);
1787	      sketchPlateRotMatrix.set(plate, rotMatrix);
1788	      return plate;
1789	    };
