const puppeteer = require('puppeteer-core');
const path = require('path');

const CHROME_PATH = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const OUT = 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/e6ba8ae5-7493-49bb-87e9-cfdb4998cd80/scratchpad/pw';
const PROFILE = path.join(OUT, 'isolated-profile');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: 'new',
    userDataDir: PROFILE,
    args: [
      '--no-sandbox', '--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist',
      '--window-size=1400,900', '--no-first-run', '--no-default-browser-check',
    ],
    defaultViewport: { width: 1400, height: 900 },
  });
  try {
    const page = await browser.newPage();
    const logs = [];
    page.on('console', (msg) => logs.push(`[console:${msg.type()}] ${msg.text()}`));
    page.on('pageerror', (err) => logs.push(`[pageerror] ${err.message}`));

    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 2500));
    await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll('button, [role="tab"], a'));
      const el = els.find((e) => (e.textContent || '').trim() === 'Modélisation');
      if (el) el.click();
    });
    await new Promise((r) => setTimeout(r, 1200));
    await page.screenshot({ path: path.join(OUT, '20-shader-grid-default.png') });

    const canvas = await page.$('#babylon-canvas');
    const box = await canvas.boundingBox();
    const cx = box.x + box.width / 2;
    const cy = box.y + box.height / 2;

    // Zoom in moderately (like the user's screenshot: a tilted, fairly close view).
    await page.mouse.move(cx, cy);
    for (let i = 0; i < 10; i++) {
      await page.mouse.wheel({ deltaY: -120 });
      await new Promise((r) => setTimeout(r, 20));
    }
    await new Promise((r) => setTimeout(r, 300));
    await page.screenshot({ path: path.join(OUT, '21-shader-grid-zoomed.png') });

    // Pan a bit off-center too.
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'right' });
    await page.mouse.move(cx - 150, cy - 100, { steps: 10 });
    await page.mouse.up({ button: 'right' });
    await new Promise((r) => setTimeout(r, 300));
    await page.screenshot({ path: path.join(OUT, '22-shader-grid-panned.png') });

    console.log('=== logs ===');
    console.log(logs.join('\n'));
  } finally {
    await browser.close();
  }
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

