void main(void) {
  // Même calcul que updateGrid côté CPU (log10 + arrondi décade), mais évalué ICI avec
  // la dérivée LOCALE de la position monde : chaque pixel choisit son propre pas plutôt
  // que d'hériter d'un pas unique calculé pour toute la scène.
  vec2 dXZ = fwidth(vWorldPos.xz);
  float worldPerPixelLocal = max(dXZ.x, dXZ.y);
  float l = log(uMinPx * worldPerPixelLocal) / log(10.0);
  // Plafonné à uMinExponent : en dessous, la précision simple précision ne suit plus (cf.
  // le commentaire sur GRID_MIN_STEP_EXPONENT côté CPU) — mieux vaut arrêter d'affiner que
  // de laisser le quadrillage devenir incohérent.
  float exponent = max(ceil(l), uMinExponent);
  float step = pow(10.0, exponent);
  // Écrêté à [0,1] : au plafond, `exponent` ne suit plus `l`, et le polynôme de lissage
  // suppose ce domaine (sinon `fade` diverge au lieu de saturer à 1).
  float t = clamp(exponent - l, 0.0, 1.0);
  float fade = t * t * (3.0 - 2.0 * t); // apparition en fondu du niveau fin, lissée

  vec2 coordFine = vWorldPos.xz / (step * 0.1);
  vec2 coordMain = vWorldPos.xz / step;
  vec2 coordDecade = vWorldPos.xz / (step * 10.0);

  float fineMask = gridMask(coordFine, 0.6) * fade;

