/**
 * Fait suivre le plan du quadrillage sous la cible caméra — mais SANS le recoller dessus à
 * chaque frame. Le shader lit une coordonnée LOCALE au maillage (`vLocalPos`, cf. plus haut),
 * pas la position monde : si on translatait le maillage à l'identique de `camera.target` à
 * chaque image, le motif resterait au contraire COLLÉ À L'ÉCRAN — puisqu'il est alors
 * réévalué, à chaque frame, relativement à un repère qui vient justement de bouger d'autant —
 * au lieu de défiler sous la caméra comme un sol qu'on survole.
 *
 * On ne redéplace donc le maillage que lorsque la cible s'éloigne trop de son ancrage actuel
 * (marge proportionnelle au pas courant). Entre deux ancrages, le maillage est immobile : le
 * motif, purement local, reste donc fixe dans l'espace monde — c'est ce qui le fait défiler
 * correctement pendant qu'on pan. Et comme le pas est toujours une puissance de dix, un saut
 * d'ancrage d'un multiple exact de la décade courante ne déplace aucun trait visible (même
 * principe que l'ancien pavage de lignes) : la marge choisie *est* ce multiple.
 */
let gridAnchorX = 0;
let gridAnchorZ = 0;
const GRID_RECENTER_MARGIN_STEPS = 200; // grand devant 1 pour rester rare, petit devant la
// taille du plan (`GRID_GROUND_HALF_SIZE`) pour ne jamais en révéler le bord.
const recenterGridGround = () => {
  const step = Math.max(gridStepScale, Math.pow(10, GRID_MIN_STEP_EXPONENT));
  const margin = GRID_RECENTER_MARGIN_STEPS * step;
  if (Math.abs(camera.target.x - gridAnchorX) <= margin && Math.abs(camera.target.z - gridAnchorZ) <= margin) {
    return;
