file.content:
  varying vec3 vLocalPos;
  uniform vec3 uMinorColor;
  uniform vec3 uMajorColor;
  uniform float uMinorAlpha;
  uniform float uMajorAlpha;
  uniform float uMinPx;
  uniform float uMinExponent;

  // Distance (en pixels, via la dérivée écran locale) au trait le plus proche d'un
  // quadrillage de pas 1 en espace coord — même principe qu'un anti-aliasing par SDF.
  float gridMask(vec2 coord, float halfWidthPx) {
    vec2 deriv = fwidth(coord);
    vec2 dist = abs(fract(coord + 0.5) - 0.5) / max(deriv, vec2(1e-6));
    float d = min(dist.x, dist.y);
    return 1.0 - clamp(d / halfWidthPx, 0.0, 1.0);
  }

  void main(void) {
    // Même calcul que updateGrid côté CPU (log10 + arrondi décade), mais évalué ICI avec
    // la dérivée LOCALE de la position monde : chaque pixel choisit son propre pas plutôt
    // que d'hériter d'un pas unique calculé pour toute la scène.
    vec2 dXZ = fwidth(vLocalPos.xz);
    float worldPerPixelLocal = max(dXZ.x, dXZ.y);
    float l = log(uMinPx * worldPerPixelLocal) / log(10.0);
    // Plafonné à uMinExponent : en dessous, la précision simple précision ne suit plus (cf.
    // le commentaire sur GRID_MIN_STEP_EXPONENT côté CPU) — mieux vaut arrêter d'affiner que
    // de laisser le quadrillage devenir incohérent.
    float exponent = max(ceil(l), uMinExponent);
    float step = pow(10.0, exponent);
    // Écrêté à [0,1] : au plafond, exponent ne suit plus l, et le polynôme de lissage
    // suppose ce domaine (sinon fade diverge au lieu de saturer à 1).
    float t = clamp(exponent - l, 0.0, 1.0);
    float fade = t * t * (3.0 - 2.0 * t); // apparition en fondu du niveau fin, lissée

    vec2 coordFine = vLocalPos.xz / (step * 0.1);
    vec2 coordMain = vLocalPos.xz / step;
    vec2 coordDecade = vLocalPos.xz / (step * 10.0);

    float fineMask = gridMask(coordFine, 0.6) * fade;
    float mainMask = gridMask(coordMain, 0.6);
    float decadeMask = gridMask(coordDecade, 0.85);

    vec3 color = uMinorColor;
    float alpha = fineMask * uMinorAlpha;
    alpha = max(alpha, mainMask * uMinorAlpha);
    if (decadeMask > 0.0) {
      color = uMajorColor;
      alpha = max(alpha, decadeMask * uMajorAlpha);
    }

    if (alpha < 0.004) discard;
    gl_FragColor = vec4(color, alpha);
  }
`;
const GRID_MIN_PX = 10;

