// Distance (en pixels) au trait le plus proche d'un quadrillage de pas `spacing`, à partir
// d'une position ET d'une dérivée déjà calculées — jamais de fwidth() ici : `spacing`
// varie de façon DISCONTINUE d'un pixel à l'autre (cf. plus bas), et rappeler fwidth() sur
// une expression qui en dépend (position / spacing) ferait comparer par différence finie
// deux pixels voisins avec des pas différents pile à la frontière — le GPU y calculerait
// n'importe quoi, masquant les traits par bandes entières à cet endroit précis de l'écran
// (fixe, puisque lié à la distance caméra-sol, pas à la position qu'on regarde).
float gridMask(vec2 worldXZ, vec2 worldDeriv, float spacing, float halfWidthPx) {
  vec2 coord = worldXZ / spacing;
  vec2 coordDeriv = worldDeriv / spacing;
  vec2 dist = abs(fract(coord + 0.5) - 0.5) / max(coordDeriv, vec2(1e-6));
  float d = min(dist.x, dist.y);
  return 1.0 - clamp(d / halfWidthPx, 0.0, 1.0);
}

void main(void) {
  // Même calcul que updateGrid côté CPU (log10 + arrondi décade), mais évalué ICI avec
  // la dérivée LOCALE de la position monde : chaque pixel choisit son propre pas plutôt
  // que d'hériter d'un pas unique calculé pour toute la scène. Seul appel à fwidth() du
  // shader, sur une grandeur continue (vLocalPos) — tout le reste s'en déduit par simple
  // arithmétique, jamais par un nouvel appel à fwidth() (cf. gridMask ci-dessus).
  vec2 worldDeriv = fwidth(vLocalPos.xz);
  float worldPerPixelLocal = max(worldDeriv.x, worldDeriv.y);
  float l = log(uMinPx * worldPerPixelLocal) / log(10.0);
  // Plafonné à uMinExponent : en dessous, la précision simple précision ne suit plus (cf.
  // le commentaire sur GRID_MIN_STEP_EXPONENT côté CPU) — mieux vaut arrêter d'affiner que
  // de laisser le quadrillage devenir incohérent.
  float exponent = max(ceil(l), uMinExponent);
  float step = pow(10.0, exponent);
  // Écrêté à [0,1] : au plafond, exponent ne suit plus l, et le polynôme de lissage
  // suppose ce domaine (sinon fade diverge au lieu de saturer à 1).
  float t = clamp(exponent - l, 0.0, 1.0);
  float fade = t * t * (3.0 - 2.0 * t); // apparition en fondu du niveau fin, lissée

  float fineMask = gridMask(vLocalPos.xz, worldDeriv, step * 0.1, 0.6) * fade;
  float mainMask = gridMask(vLocalPos.xz, worldDeriv, step, 0.6);
  float decadeMask = gridMask(vLocalPos.xz, worldDeriv, step * 10.0, 0.85);

