// pixel loin du centre de l'écran (donc à une distance caméra très différente) peut
// localement réclamer un pas bien plus grossier que le pas central (cf. le shader, calcul
// par pixel) — c'était le cas avec seulement 2 décades de marge, provoquant un micro-saut
// visible pile au ré-ancrage, qui coïncide justement avec les changements de décade. On
// plafonne quand même la période pour ne jamais approcher le bord du plan (dont la demi-
// taille borne le décalage max entre cible et ancre après un saut).
const period = Math.min(step * 100000, GRID_GROUND_HALF_SIZE / 4);
// Si le pas central est déjà plus grossier que ce plafond (zoom très arrière), la période
// doit rester au moins égale à ce pas pour continuer à couvrir SA propre décade.
const effectivePeriod = Math.max(period, step * 10);

