content.content:
    BABYLON.Effect.ShadersStore["modelingGridVertexShader"] = `
      precision highp float;
      attribute vec3 position;
      uniform mat4 worldViewProjection;
      // Coordonnée LOCALE au maillage (avant la matrice world), pas la position monde absolue :
      // ce plan est recentré sous la cible caméra à chaque frame (cf. recenterGridGround), donc
      // sa position locale reste petite (bornée par sa propre taille) même très loin de l'origine
      // monde. Diviser par un pas microscopique une position monde absolue (qui peut valoir des
      // centaines de mm) fait perdre toute précision fractionnaire en simple précision — c'est la
      // cause des artefacts sous 1 mm ; rester en local évite le problème à la racine.
      varying vec3 vLocalPos;
      void main(void) {
        vLocalPos = position;
        gl_Position = worldViewProjection * vec4(position, 1.0);
      }
    `;
    BABYLON.Effect.ShadersStore["modelingGridFragmentShader"] = `
      precision highp float;
      varying vec3 vLocalPos;
      uniform vec3 uMinorColor;
----
      float gridMask(vec2 worldXZ, vec2 worldDeriv, float spacing, float halfWidthPx) {
        vec2 coord = worldXZ / spacing;
        vec2 coordDeriv = worldDeriv / spacing;
        vec2 dist = abs(fract(coord + 0.5) - 0.5) / max(coordDeriv, vec2(1e-6));
        float d = min(dist.x, dist.y);
        return 1.0 - clamp(d / halfWidthPx, 0.0, 1.0);
      }

      void main(void) {
        // Même calcul que updateGrid côté CPU (log10 + arrondi décade), mais évalué ICI avec
        // la dérivée LOCALE de la position monde : chaque pixel choisit son propre pas plutôt
        // que d'hériter d'un pas unique calculé pour toute la scène. Seul appel à fwidth() du
        // shader, sur une grandeur continue (vLocalPos) — tout le reste s'en déduit par simple
        // arithmétique, jamais par un nouvel appel à fwidth() (cf. gridMask ci-dessus).
        vec2 worldDeriv = fwidth(vLocalPos.xz);
        float worldPerPixelLocal = max(worldDeriv.x, worldDeriv.y);
        float l = log(uMinPx * worldPerPixelLocal) / log(10.0);
----
        float mainMask = gridMask(vLocalPos.xz, worldDeriv, step, 0.6);
        float decadeMask = gridMask(vLocalPos.xz, worldDeriv, step * 10.0, 0.85);

        vec3 color = uMinorColor;
        float alpha = fineMask * uMinorAlpha;
        alpha = max(alpha, mainMask * uMinorAlpha);
        if (decadeMask > 0.0) {
          color = uMajorColor;
          alpha = max(alpha, decadeMask * uMajorAlpha);
