/**
 * Fait suivre le plan du quadrillage sous la cible caméra — mais SANS le recoller dessus à
 * chaque frame. Le shader lit une coordonnée LOCALE au maillage (`vLocalPos`, cf. plus haut),
 * pas la position monde : si on translatait le maillage à l'identique de `camera.target` à
 * chaque image, le motif resterait au contraire COLLÉ À L'ÉCRAN — puisqu'il est alors
 * réévalué, à chaque frame, relativement à un repère qui vient justement de bouger d'autant —
 * au lieu de défiler sous la caméra comme un sol qu'on survole.
 *
 * On ne redéplace donc le maillage que lorsque la cible s'éloigne trop de son ancrage actuel
 * (marge proportionnelle au pas courant). Entre deux ancrages, le maillage est immobile : le
 * motif, purement local, reste donc fixe dans l'espace monde — c'est ce qui le fait défiler
 * correctement pendant qu'on pan. Et comme le pas est toujours une puissance de dix, un saut
 * d'ancrage d'un multiple exact de la décade courante ne déplace aucun trait visible (même
 * principe que l'ancien pavage de lignes) : la marge choisie *est* ce multiple.
 */
let gridAnchorX = 0;
let gridAnchorZ = 0;
const GRID_RECENTER_MARGIN_STEPS = 200; // grand devant 1 pour rester rare, petit devant la
// taille du plan (`GRID_GROUND_HALF_SIZE`) pour ne jamais en révéler le bord.
const recenterGridGround = () => {
  const step = Math.max(gridStepScale, Math.pow(10, GRID_MIN_STEP_EXPONENT));
  const margin = GRID_RECENTER_MARGIN_STEPS * step;
  if (Math.abs(camera.target.x - gridAnchorX) <= margin && Math.abs(camera.target.z - gridAnchorZ) <= margin) {
    return;
  }
  // Large avance de décades sur le pas central (pas juste une ou deux) : en perspective, un
  // pixel loin du centre de l'écran (donc à une distance caméra très différente) peut
  // localement réclamer un pas bien plus grossier que le pas central (cf. le shader, calcul
  // par pixel) — c'était le cas avec seulement 2 décades de marge, provoquant un micro-saut
  // visible pile au ré-ancrage, qui coïncide justement avec les changements de décade. On
  // plafonne quand même la période pour ne jamais approcher le bord du plan (dont la demi-
  // taille borne le décalage max entre cible et ancre après un saut).
  const period = Math.min(step * 100000, GRID_GROUND_HALF_SIZE / 4);
  // Si le pas central est déjà plus grossier que ce plafond (zoom très arrière), la période
  // doit rester au moins égale à ce pas pour continuer à couvrir SA propre décade.
  const effectivePeriod = Math.max(period, step * 10);
  gridAnchorX = Math.round(camera.target.x / effectivePeriod) * effectivePeriod;
  gridAnchorZ = Math.round(camera.target.z / effectivePeriod) * effectivePeriod;
  modelingGridGround.position.set(gridAnchorX, 0, gridAnchorZ);
};

// Empêche de « passer au travers » du plan de travail en zoomant : au lieu de traverser,
// la grille se subdivise et la caméra reste à distance de sa cible — jusqu'à ce que le pas
// touche `GRID_MIN_STEP_EXPONENT` (cf. plus haut), où la caméra s'arrête tout à fait plutôt
// que de continuer sur une grille devenue incohérente en simple précision. Inverse exact de
// `worldPerPixel = 2·radius·tan(fov/2) / hauteur` pour le `worldPerPixel` qui fait tout juste
// atteindre ce pas plancher.
const minWorldPerPixel = Math.pow(10, GRID_MIN_STEP_EXPONENT) / GRID_MIN_PX;
camera.lowerRadiusLimit = (minWorldPerPixel * engine.getRenderHeight()) / (2 * Math.tan(camera.fov / 2));
camera.upperRadiusLimit = 100000;
// `camera.minZ` (plan de clipping proche) vaut 0.1 par défaut et n'était jamais réduit : une
// fois le rayon caméra descendu bien en dessous, ce plan proche coupait TOUTE la géométrie
// visible (la grille entière disparaissait) plutôt que de simplement s'affiner — bien plus
// grave qu'un artefact local. Il doit rester très inférieur au rayon minimal autorisé pour
// ne jamais couper ce qu'on regarde, même au plancher de zoom.
camera.minZ = camera.lowerRadiusLimit / 100;
let gridZoomLimitReached = false;
(window as any).__debugGrid3 = () => ({
  radius: camera.radius, lowerLimit: camera.lowerRadiusLimit, minZ: camera.minZ,
  gridStepScale, groundEnabled: modelingGridGround.isEnabled(),
  groundVisible: modelingGridGround.isVisible, groundPos: modelingGridGround.position.asArray(),
  matAlpha: modelingGridMat.alpha,
});

/**
 * Barre d'échelle du mode modélisation. Pour une caméra en perspective, un pixel au niveau

