  void main(void) {
    // Même calcul que updateGrid côté CPU (log10 + arrondi décade), mais évalué ICI avec
    // la dérivée LOCALE de la position monde : chaque pixel choisit son propre pas plutôt
    // que d'hériter d'un pas unique calculé pour toute la scène. Seul appel à fwidth() du
    // shader, sur une grandeur continue (vGridPos) — tout le reste s'en déduit par simple
    // arithmétique, jamais par un nouvel appel à fwidth() (cf. gridMask ci-dessus).
    vec2 worldDeriv = fwidth(vGridPos);
    float worldPerPixelLocal = max(worldDeriv.x, worldDeriv.y);
    float l = log(uMinPx * worldPerPixelLocal) / log(10.0);
    // Plafonné à uMinExponent : en dessous, la précision simple précision ne suit plus (cf.
    // le commentaire sur GRID_MIN_STEP_EXPONENT côté CPU) — mieux vaut arrêter d'affiner que
    // de laisser le quadrillage devenir incohérent.
    float exponent = max(ceil(l), uMinExponent);
    float step = pow(10.0, exponent);
    // Écrêté à [0,1] : au plafond, exponent ne suit plus l, et le polynôme de lissage
    // suppose ce domaine (sinon fade diverge au lieu de saturer à 1).
    float t = clamp(exponent - l, 0.0, 1.0);
    float fade = t * t * (3.0 - 2.0 * t); // apparition en fondu du niveau fin, lissée

    float fineMask = gridMask(vGridPos, worldDeriv, step * 0.1, 0.6) * fade;
    float mainMask = gridMask(vGridPos, worldDeriv, step, 0.6);
    float decadeMask = gridMask(vGridPos, worldDeriv, step * 10.0, 0.85);

    vec3 color = uMinorColor;
    float alpha = fineMask * uMinorAlpha;
    alpha = max(alpha, mainMask * uMinorAlpha);
    if (decadeMask > 0.0) {
      color = uMajorColor;
      alpha = max(alpha, decadeMask * uMajorAlpha);
    }

    if (alpha < 0.004) discard;
    gl_FragColor = vec4(color, alpha);
  }
`;

