const puppeteer = require('puppeteer-core');
const path = require('path');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: 'new', userDataDir: path.join(__dirname, 'isolated-profile8'),
    args: ['--no-sandbox','--use-gl=swiftshader','--enable-webgl','--ignore-gpu-blocklist','--window-size=1230,1000','--no-first-run'],
    defaultViewport: { width: 1230, height: 1000 },
  });
  try {
    const page = await browser.newPage();
    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 2500));
    await page.evaluate(() => {
      const el = Array.from(document.querySelectorAll('button, a')).find((e) => (e.textContent || '').trim() === 'Modélisation');
      if (el) el.click();
    });
    await new Promise((r) => setTimeout(r, 1500));
    const box = await (await page.$('#babylon-canvas')).boundingBox();
    const cx = box.x + box.width / 2, cy = box.y + box.height / 2;
    await page.mouse.move(cx, cy);
    const r = () => page.evaluate(() => window.__camDebug.radius);
    const settle = () => new Promise((res) => setTimeout(res, 900));
    // One notch at a time, zooming in: ratio per notch.
    let prev = await r();
    const ins = [];
    for (let i = 0; i < 8; i++) {
      await page.mouse.wheel({ deltaY: -100 }); await settle();
      const cur = await r(); ins.push((cur / prev).toFixed(3)); prev = cur;
    }
    console.log('zoom-in ratio per notch:', ins.join(' '), '| radius now', prev.toExponential(3));
    // Notches needed to go from current to the floor.
    let n = 0;
    while (n < 400) {
      const before = await r();
      await page.mouse.wheel({ deltaY: -100 }); await new Promise((res) => setTimeout(res, 150));
      n++;
      const lim = await page.evaluate(() => window.__camDebug.lowerRadiusLimit);
      if (before <= lim * 1.0001) break;
    }
    console.log('notches to reach floor:', n, 'radius', (await r()).toExponential(3));
    // Zoom-out ratio per notch.
    prev = await r(); const outs = [];
    for (let i = 0; i < 5; i++) {
      await page.mouse.wheel({ deltaY: 100 }); await settle();
      const cur = await r(); outs.push((cur / prev).toFixed(3)); prev = cur;
    }
    console.log('zoom-out ratio per notch:', outs.join(' '));
    // Pan tracking: drag 200 px, compare target displacement to world-per-pixel * 200.
    for (const label of ['close', 'far']) {
      if (label === 'far') { for (let i = 0; i < 60; i++) { await page.mouse.wheel({ deltaY: 100 }); await new Promise((res) => setTimeout(res, 40)); } await settle(); }
      const st = await page.evaluate(() => { const c = window.__camDebug; return { x: c.target.x, z: c.target.z, r: c.radius, fov: c.fov }; });
      await page.mouse.move(cx, cy); await page.mouse.down({ button: 'right' });
      await page.mouse.move(cx + 200, cy, { steps: 20 }); await page.mouse.up({ button: 'right' });
      await new Promise((res) => setTimeout(res, 1500));
      const en = await page.evaluate(() => { const c = window.__camDebug; return { x: c.target.x, z: c.target.z }; });
      const moved = Math.hypot(en.x - st.x, en.z - st.z);
      const wpp = 2 * st.r * Math.tan(st.fov / 2) / 1000;
      console.log(`pan ${label}: radius=${st.r.toExponential(3)} moved=${moved.toExponential(3)} expected~${(wpp * 200).toExponential(3)} ratio=${(moved / (wpp * 200)).toFixed(2)}`);
    }
  } finally { await browser.close(); }
})().catch((e) => { console.error('FATAL', e); process.exit(1); });
EOF
