    const GRID_LABEL_PLANE_PX = 22; // hauteur du panneau à l'écran (glyphe ≈ 60 % de celle-ci)
    const GRID_LABEL_GAP_PX = 6; // marge entre deux chiffres, et entre un chiffre et son axe
