        const acrossFootprint = (Math.abs(c.x) * planeW + Math.abs(c.y) * planeH) / Math.max(Math.hypot(c.x, c.y), 1e-6);
        const offset = ((acrossFootprint * 0.35 + GRID_LABEL_GAP_PX) * worldPerPixel) / acrossLen;
        mesh.position.set(axis === 'x' ? along : offset, 0, axis === 'z' ? along : offset);
      });
    };
