const puppeteer = require('puppeteer-core');
const path = require('path');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: 'new', userDataDir: path.join(__dirname, 'isolated-profile14'),
    args: ['--no-sandbox','--use-angle=d3d11','--enable-gpu','--ignore-gpu-blocklist','--window-size=1240,1000','--no-first-run'],
    defaultViewport: { width: 1240, height: 1000 },
  });
  try {
    const page = await browser.newPage();
    const errs = [];
    page.on('pageerror', (e) => errs.push(e.message));
    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 2500));
    await page.evaluate(() => {
      const el = Array.from(document.querySelectorAll('button, a')).find((e) => (e.textContent || '').trim() === 'Modélisation');
      if (el) el.click();
    });
    await new Promise((r) => setTimeout(r, 1500));
    // Ground point under a given page pixel, and screen position of a world point.
    const probe = (px, py) => page.evaluate((px, py) => {
      const s = window.__sceneDebug, c = s.activeCamera, cv = s.getEngine().getRenderingCanvas();
      const r = cv.getBoundingClientRect();
      const ray = s.createPickingRay(px - r.left, py - r.top, BABYLON.Matrix.Identity(), c);
      const t = -ray.origin.y / ray.direction.y;
      return { x: ray.origin.x + ray.direction.x * t, z: ray.origin.z + ray.direction.z * t, radius: c.radius };
    }, px, py);
    const toScreen = (p) => page.evaluate((p) => {
      const s = window.__sceneDebug, c = s.activeCamera, e = s.getEngine(), cv = e.getRenderingCanvas();
      const r = cv.getBoundingClientRect();
      const v = BABYLON.Vector3.Project(new BABYLON.Vector3(p.x, 0, p.z), BABYLON.Matrix.Identity(), s.getTransformMatrix(),
        c.viewport.toGlobal(e.getRenderWidth(), e.getRenderHeight()));
      const k = r.width / e.getRenderWidth();
      return { x: v.x * k + r.left, y: v.y * k + r.top };
    }, p);
    for (const [mx, my, dir, n] of [[950, 750, -100, 12], [450, 350, -100, 25], [450, 350, 100, 15]]) {
      await page.mouse.move(mx, my);
      await new Promise((r) => setTimeout(r, 200));
      const g = await probe(mx, my);
      for (let i = 0; i < n; i++) { await page.mouse.wheel({ deltaY: dir }); await new Promise((r) => setTimeout(r, 30)); }
      await new Promise((r) => setTimeout(r, 1500));
      const scr = await toScreen(g);
      const after = await probe(mx, my);
      console.log(`cursor(${mx},${my}) ${dir < 0 ? 'in ' : 'out'} x${n}: radius ${g.radius.toExponential(2)} -> ${after.radius.toExponential(2)}, anchored point now at (${scr.x.toFixed(1)}, ${scr.y.toFixed(1)}) drift=${Math.hypot(scr.x - mx, scr.y - my).toFixed(2)}px`);
    }
    await page.screenshot({ path: path.join(__dirname, 'e0-after.png') });
    console.log('errors:', errs.length ? errs.join('\n') : 'none');
  } finally { await browser.close(); }
})().catch((e) => { console.error('FATAL', e); process.exit(1); });
EOF
