      void main(void) {
        // Seul appel à fwidth() du shader, sur une grandeur continue (vGridPos) — tout le reste
        // s'en déduit par simple arithmétique (cf. gridMask ci-dessus).
        vec2 worldDeriv = fwidth(vGridPos);
        float worldPerPixel = max(max(worldDeriv.x, worldDeriv.y), 1e-12);
        float l = log(uMinPx * worldPerPixel) / log(10.0);
        // Décade de base : la plus grande puissance de dix dont l'espacement à l'écran reste sous
        // uMinPx pixels (donc invisible). Plancher à uMinExponent - 1 : le plus fin des niveaux
        // tracés ne descend jamais sous 10^uMinExponent (limite de précision, cf. CPU).
        float baseExp = max(floor(l), uMinExponent - 1.0);

        // Aucune étiquette discrète (fin / principal / décade) : chaque famille de traits (pas
        // 10^k) a une intensité, une couleur et une épaisseur fonctions CONTINUES de son propre
        // espacement à l'écran. Un même trait garde donc exactement le même rendu quand le pixel
        // bascule d'une décade à la suivante (seul baseExp change, et les niveaux se décalent
        // d'un cran sans rien modifier). Avec des étiquettes, un trait « décade » (clair, épais)
        // devenait brutalement « principal » (terne) à cette frontière — fixe à l'écran car liée
        // à la distance caméra — d'où les coupures qui revenaient à chaque décade.
        vec3 color = uMinorColor;
        float alpha = 0.0;
        for (int k = 1; k <= 3; k++) {
          float spacing = pow(10.0, baseExp + float(k));
          // 0 à uMinPx px (le trait apparaît), 1 à 100 × uMinPx px (trait majeur).
          float t = clamp(log(spacing / (worldPerPixel * uMinPx)) / log(10.0) * 0.5, 0.0, 1.0);
          float w = t * t * (3.0 - 2.0 * t);
          float mask = gridMask(vGridPos, worldDeriv, spacing, mix(0.6, 0.85, w));
          float a = mask * uMajorAlpha * w;
          if (a > alpha) {
            alpha = a;
            color = mix(uMinorColor, uMajorColor, w);
          }
        }

        // Fondu vers le bord du plan : sa limite ne se voit jamais, même en vue rasante.
        alpha *= 1.0 - smoothstep(0.6, 1.0, length(vUnitPos));

        if (alpha < 0.004) discard;
        gl_FragColor = vec4(color, alpha);
      }
    `;
