const puppeteer = require('puppeteer-core');
const path = require('path');
const OUT = __dirname;
(async () => {
  const browser = await puppeteer.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: 'new', userDataDir: path.join(OUT, 'isolated-orbit'),
    args: ['--no-sandbox', '--use-angle=d3d11', '--enable-gpu', '--ignore-gpu-blocklist', '--window-size=1240,1000'],
    defaultViewport: { width: 1240, height: 1000 },
  });
  try {
    const page = await browser.newPage();
    page.on('pageerror', (e) => console.log('pageerror', e.message));
    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 3000));
    const box = await (await page.$('#babylon-canvas')).boundingBox();
    const cx = box.x + box.width / 2, cy = box.y + box.height / 2;
    const dbg = () => page.evaluate(() => window.__orbitDebug());
    console.log('start', await dbg());
    // zoom toward an off-center point, then pan
    await page.mouse.move(cx + 200, cy + 100);
    for (let i = 0; i < 5; i++) { await page.mouse.wheel({ deltaY: -100 }); await new Promise((r) => setTimeout(r, 30)); }
    await new Promise((r) => setTimeout(r, 600));
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'right' });
    await page.mouse.move(cx - 120, cy + 60, { steps: 10 });
    await page.mouse.up({ button: 'right' });
    await new Promise((r) => setTimeout(r, 400));
    const before = await dbg();
    console.log('after zoom+pan', before);
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'left' });
    await page.mouse.move(cx + 250, cy - 120, { steps: 20 });
    await page.mouse.up({ button: 'left' });
    for (let i = 0; i < 6; i++) { await new Promise((r) => setTimeout(r, 250)); console.log('orbit', await dbg()); }
  } finally { await browser.close(); }
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

