2420	    // Trouve, sur le plateau circulaire, la position libre la plus proche du centre pour un
2421	    // nouveau modèle (approximé par son cercle englobant en X/Z), par circle-packing : en
2422	    // configuration optimale, une position libre la plus proche est toujours tangente soit au
2423	    // bord du plateau, soit à un modèle existant, soit à deux modèles existants à la fois — on
2424	    // génère donc ces candidats géométriques précis plutôt que d'échantillonner au hasard, avec
2425	    // une recherche par grille fine en filet de sécurité si aucun candidat n'est valide.
2426	    const findFreeSpot = (footprintRadius: number): { x: number; z: number } => {
2427	      const existing = Array.from(modelsRef.current).map((m) => {
2428	        m.computeWorldMatrix(true);
2429	        const b = m.getHierarchyBoundingVectors(true);
2430	        const c = b.min.add(b.max).scale(0.5);
2431	        const fr = Math.max(b.max.x - b.min.x, b.max.z - b.min.z) / 2;
2432	        return { x: c.x, z: c.z, r: fr };
2433	      });
2434	
2435	      const margin = 5;
2436	      const maxReach = RADIUS - footprintRadius - 2;
2437	      if (maxReach <= 0) return { x: 0, z: 0 };
2438	
2439	      const collides = (x: number, z: number) =>
2440	        existing.some((e) => Math.hypot(x - e.x, z - e.z) < footprintRadius + e.r + margin);
2441	
2442	      if (existing.length === 0 || !collides(0, 0)) return { x: 0, z: 0 };
2443	
2444	      const candidates: { x: number; z: number }[] = [];
2445	      const ANGLE_STEPS = 180;
2446	
2447	      // Tangent à chaque modèle existant, dans toutes les directions
2448	      existing.forEach((e) => {
2449	        const rr = footprintRadius + e.r + margin;
2450	        for (let i = 0; i < ANGLE_STEPS; i++) {
2451	          const a = (i / ANGLE_STEPS) * Math.PI * 2;
2452	          candidates.push({ x: e.x + rr * Math.cos(a), z: e.z + rr * Math.sin(a) });
2453	        }
2454	      });
2455	
2456	      // Tangent à deux modèles existants simultanément (intersection des deux cercles de
2457	      // sécurité) — c'est là que se trouvent les emplacements les plus compacts en packing.
2458	      for (let i = 0; i < existing.length; i++) {
2459	        for (let j = i + 1; j < existing.length; j++) {
2460	          const a = existing[i];
2461	          const b = existing[j];
2462	          const ra = footprintRadius + a.r + margin;
2463	          const rb = footprintRadius + b.r + margin;
2464	          const dx = b.x - a.x;
2465	          const dz = b.z - a.z;
2466	          const d = Math.hypot(dx, dz);
2467	          if (d === 0 || d > ra + rb) continue;
2468	          const aDist = (ra * ra - rb * rb + d * d) / (2 * d);
2469	          const h2 = ra * ra - aDist * aDist;
2470	          if (h2 < 0) continue;
2471	          const h = Math.sqrt(h2);
2472	          const mx = a.x + (aDist * dx) / d;
2473	          const mz = a.z + (aDist * dz) / d;
2474	          candidates.push({ x: mx + (h * dz) / d, z: mz - (h * dx) / d });
2475	          candidates.push({ x: mx - (h * dz) / d, z: mz + (h * dx) / d });
2476	        }
2477	      }
2478	
2479	      const valid = candidates
2480	        .filter((c) => Math.hypot(c.x, c.z) <= maxReach && !collides(c.x, c.z))
2481	        .sort((p, q) => Math.hypot(p.x, p.z) - Math.hypot(q.x, q.z));
2482	
2483	      if (valid.length > 0) return valid[0];
2484	
2485	      // Filet de sécurité : balayage fin de tout le plateau, on garde le point valide le
2486	      // plus proche du centre rencontré.
2487	      const step = 2;
2488	      let best: { x: number; z: number } | null = null;
2489	      let bestDist = Infinity;
2490	      for (let x = -maxReach; x <= maxReach; x += step) {
2491	        for (let z = -maxReach; z <= maxReach; z += step) {
2492	          const d = Math.hypot(x, z);
2493	          if (d > maxReach || d >= bestDist || collides(x, z)) continue;
2494	          best = { x, z };
2495	          bestDist = d;
2496	        }
2497	      }
2498	      return best ?? { x: 0, z: 0 };
2499	    };
