2526	          }
2527	          r.name = uniqueName;
2528	
2529	          if (isGlbOrGltf) {
2530	            // Les fichiers glTF/GLB utilisent le mètre par convention, alors que la scène et
2531	            // le volume d'impression sont en millimètres (RADIUS/HEIGHT) — sans cette mise à
2532	            // l'échelle, un modèle réel de quelques cm devient un point microscopique invisible.
2533	            r.scaling.scaleInPlace(1000);
2534	          }
2535	
2536	          r.computeWorldMatrix(true);
2537	          const boundingInfo = r.getHierarchyBoundingVectors(true);
2538	          const center = boundingInfo.min.add(boundingInfo.max).scale(0.5);
2539	          const footprintRadius = Math.max(boundingInfo.max.x - boundingInfo.min.x, boundingInfo.max.z - boundingInfo.min.z) / 2;
2540	          const spot = findFreeSpot(footprintRadius);
2541	
2542	          // Place le modèle sur un emplacement libre du plateau (au lieu de toujours l'origine,
