2546	          // et interrompt l'import avant que le modèle ne soit positionné/rendu visible.
2547	          r.position.addInPlace(new BABYLON.Vector3(spot.x - center.x, -boundingInfo.min.y, spot.z - center.z));
2548	
2549	          if (!isGlbOrGltf) {
2550	            // Les STL ne portent aucune info de matériau : on applique une teinte neutre par
2551	            // défaut (le shader de zone d'exclusion de l'imprimante est réservé aux parois du
2552	            // volume et culle les faces arrière, ce qui rend invisible tout STL aux normales
2553	            // inversées — cas fréquent selon le logiciel d'export).
2554	            const defaultMat = new BABYLON.StandardMaterial("stlDefaultMat", scene);
2555	            defaultMat.diffuseColor = new BABYLON.Color3(0.6, 0.65, 0.7);
2556	            defaultMat.backFaceCulling = false;
2557	            r.material = defaultMat;
2558	          }
2559	
2560	          modelsRef.current.add(r);
2561	          selectedMeshesRef.current.clear();
2562	          selectedMeshesRef.current.add(r);
2563	          setSelectedMeshName(r.name || "Modèle 3D");
2564	          updateHighlight();
2565	          updateSelectedPosition();
2566	          updateSelectedRotation();
2567	
2568	          const subMeshesList: { id: string; name: string; color: string }[] = [];
2569	          const childMeshes = [r, ...r.getChildMeshes()];
2570	          childMeshes.forEach((cm, idx) => {
2571	            let hex = '#00f0ff';
2572	            if (cm.material) {
2573	              const mat = cm.material as InspectableMaterial;
2574	              if (mat.albedoColor) hex = mat.albedoColor.toHexString();
2575	              else if (mat.diffuseColor) hex = mat.diffuseColor.toHexString();
2576	            }
2577	            subMeshesList.push({
2578	              id: `${r.name}-${idx}`,
2579	              name: cm.name || `Partie ${idx + 1}`,
2580	              color: hex
2581	            });
2582	          });
2583	
2584	          window.dispatchEvent(
2585	            new CustomEvent('apex-mesh-selected', { 
2586	              detail: { 
2587	                name: r.name || "Modèle 3D",
2588	                subMeshes: subMeshesList
2589	              }
2590	            })
2591	          );
2592	
2593	          if (currentToolRef.current === 'move') {
2594	            gizmoManager.rotationGizmoEnabled = false;
2595	            gizmoManager.scaleGizmoEnabled = false;
2596	            gizmoManager.positionGizmoEnabled = true;
