const PLATE_ARC_SAMPLE_MIN_DEG = -80;
const PLATE_ARC_SAMPLE_MAX_DEG = 170;
let lastPlateArcKey = '';
const publishPlateArc = (segments: PlateArcSegment[] | null) => {
  const key = segments ? segments.map((s) => s.d).join('|') : '';
  if (key === lastPlateArcKey) return;
  lastPlateArcKey = key;
  window.dispatchEvent(new CustomEvent('apex-plate-arc-layout', { detail: segments }));
};
const plateArcObserver = scene.onAfterRenderObservable.add(() => {
  if (modelingActive) { publishPlateArc(null); return; }
  const renderW = engine.getRenderWidth();
  const renderH = engine.getRenderHeight();
  if (!renderW || !renderH) return;
  const cssPerPx = canvas.clientWidth / renderW;
  const transform = scene.getTransformMatrix();
  const viewport = camera.viewport.toGlobal(renderW, renderH);
  const project = (p: BABYLON.Vector3) => {
    const s = BABYLON.Vector3.Project(p, BABYLON.Matrix.Identity(), transform, viewport);
    return s.z > 0 && s.z < 1 ? { x: s.x * cssPerPx, y: s.y * cssPerPx } : null;
  };

  // Repère horizontal lié à la caméra : `toward` pointe vers la caméra, `left` vers la
  // gauche de l'écran (déterminé par projection, pour ne dépendre d'aucune convention).
  const toward = new BABYLON.Vector3(Math.cos(camera.alpha), 0, Math.sin(camera.alpha));
  let left = new BABYLON.Vector3(-Math.sin(camera.alpha), 0, Math.cos(camera.alpha));
  const center = project(BABYLON.Vector3.Zero());
  const probe = project(left.scale(RADIUS));
  if (!center || !probe) { publishPlateArc(null); return; }
  if (probe.x > center.x) left = left.negate();

  // Bord du plateau projeté, finement échantillonné, avec sa normale écran sortante.
  const edge: { x: number; y: number }[] = [];
  for (let deg = PLATE_ARC_SAMPLE_MIN_DEG; deg <= PLATE_ARC_SAMPLE_MAX_DEG; deg++) {
    const a = (deg * Math.PI) / 180;
    const p = project(left.scale(RADIUS * Math.cos(a)).addInPlace(toward.scale(RADIUS * Math.sin(a))));
    if (!p) { publishPlateArc(null); return; }
    edge.push(p);
  }
  const midOffset = PLATE_ARC_GAP_PX + PLATE_ARC_THICKNESS_PX / 2;
  const normals = edge.map((p, i) => {
    const a = edge[Math.max(i - 1, 0)];
    const b = edge[Math.min(i + 1, edge.length - 1)];
    let nx = -(b.y - a.y);
    let ny = b.x - a.x;
    const len = Math.hypot(nx, ny) || 1;
    nx /= len; ny /= len;
    if (nx * (p.x - center.x) + ny * (p.y - center.y) < 0) { nx = -nx; ny = -ny; }
    return { x: nx, y: ny };
  });
  // Abscisse curviligne mesurée sur l'axe de la rangée (pas sur le bord), pour que les
  // boutons aient la même longueur à l'écran quelle que soit la courbure.
  const arcLen = [0];
  for (let i = 1; i < edge.length; i++) {
    const ax = edge[i - 1].x + normals[i - 1].x * midOffset;
    const ay = edge[i - 1].y + normals[i - 1].y * midOffset;
    const bx = edge[i].x + normals[i].x * midOffset;
    const by = edge[i].y + normals[i].y * midOffset;
    arcLen.push(arcLen[i - 1] + Math.hypot(bx - ax, by - ay));
  }
  const totalLen = arcLen[arcLen.length - 1];
  const rowLen = PLATE_ARC_BUTTONS * PLATE_ARC_BUTTON_PX + (PLATE_ARC_BUTTONS - 1) * PLATE_ARC_SPACING_PX;
  if (totalLen < rowLen) { publishPlateArc(null); return; }

  // Point, normale et tangente de la courbe à l'abscisse `s`.
  const sampleAt = (s: number) => {
    let i = 1;
    while (i < arcLen.length - 1 && arcLen[i] < s) i++;
    const span = arcLen[i] - arcLen[i - 1] || 1;
    const t = Math.min(Math.max((s - arcLen[i - 1]) / span, 0), 1);
    const p0 = edge[i - 1], p1 = edge[i];
    const n0 = normals[i - 1], n1 = normals[i];
    let nx = n0.x + (n1.x - n0.x) * t;
    let ny = n0.y + (n1.y - n0.y) * t;
    const nl = Math.hypot(nx, ny) || 1;
    nx /= nl; ny /= nl;
    // Tangente orientée dans le sens de parcours (abscisse croissante).
    let tx = p1.x - p0.x, ty = p1.y - p0.y;
    const tl = Math.hypot(tx, ty) || 1;
    tx /= tl; ty /= tl;
    return { x: p0.x + (p1.x - p0.x) * t, y: p0.y + (p1.y - p0.y) * t, nx, ny, tx, ty };
  };

  const centerIndex = PLATE_ARC_CENTER_DEG - PLATE_ARC_SAMPLE_MIN_DEG;
  const start = Math.min(Math.max(arcLen[centerIndex] - rowLen / 2, 0), totalLen - rowLen);
  const capR = PLATE_ARC_THICKNESS_PX / 2;
  const fmt = (x: number, y: number) => `${x.toFixed(1)} ${y.toFixed(1)}`;
  const SIDE_STEPS = 8;
  const CAP_STEPS = 8;
  const segments: PlateArcSegment[] = [];
  for (let k = 0; k < PLATE_ARC_BUTTONS; k++) {
    const first = k === 0;
    const last = k === PLATE_ARC_BUTTONS - 1;
    // Les extrémités de la rangée sont arrondies ; le demi-cercle prend sur la longueur du
    // bouton pour que tous les boutons gardent la même taille visible.
    const a = start + k * (PLATE_ARC_BUTTON_PX + PLATE_ARC_SPACING_PX) + (first ? capR : 0);
    const b = start + k * (PLATE_ARC_BUTTON_PX + PLATE_ARC_SPACING_PX) + PLATE_ARC_BUTTON_PX - (last ? capR : 0);
    const samples = Array.from({ length: SIDE_STEPS + 1 }, (_, j) => sampleAt(a + ((b - a) * j) / SIDE_STEPS));
    const pts: string[] = [];
    samples.forEach((q) => pts.push(fmt(q.x + q.nx * PLATE_ARC_GAP_PX, q.y + q.ny * PLATE_ARC_GAP_PX)));
    if (last) {
      const q = samples[samples.length - 1];
      const cx = q.x + q.nx * midOffset, cy = q.y + q.ny * midOffset;
      for (let j = 1; j < CAP_STEPS; j++) {
        const psi = (Math.PI * j) / CAP_STEPS;
        pts.push(fmt(cx + capR * (-Math.cos(psi) * q.nx + Math.sin(psi) * q.tx), cy + capR * (-Math.cos(psi) * q.ny + Math.sin(psi) * q.ty)));
      }
    }
    const outer = PLATE_ARC_GAP_PX + PLATE_ARC_THICKNESS_PX;
    for (let j = samples.length - 1; j >= 0; j--) {
      const q = samples[j];
      pts.push(fmt(q.x + q.nx * outer, q.y + q.ny * outer));
    }
    if (first) {
      const q = samples[0];
      const cx = q.x + q.nx * midOffset, cy = q.y + q.ny * midOffset;
      for (let j = 1; j < CAP_STEPS; j++) {
        const psi = (Math.PI * j) / CAP_STEPS;
        pts.push(fmt(cx + capR * (Math.cos(psi) * q.nx - Math.sin(psi) * q.tx), cy + capR * (Math.cos(psi) * q.ny - Math.sin(psi) * q.ty)));
      }
    }
    const m = sampleAt((a + b) / 2);
    const labelOffset = outer + 10;
    segments.push({
      d: `M ${pts.join(' L ')} Z`,
      cx: m.x + m.nx * midOffset,
      cy: m.y + m.ny * midOffset,
      lx: m.x + m.nx * labelOffset,
      ly: m.y + m.ny * labelOffset,
      labelSide: m.nx < 0 ? 'left' : 'right',
    });
  }
  publishPlateArc(segments);
});

