const puppeteer = require('puppeteer-core');
const path = require('path');
const OUT = __dirname;
(async () => {
  const browser = await puppeteer.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: 'new', userDataDir: path.join(OUT, 'isolated-arc'),
    args: ['--no-sandbox', '--use-angle=d3d11', '--enable-gpu', '--ignore-gpu-blocklist', '--window-size=1400,900'],
    defaultViewport: { width: 1400, height: 900 },
  });
  try {
    const page = await browser.newPage();
    page.on('pageerror', (e) => console.log('pageerror', e.message));
    page.on('console', (m) => { if (m.type() === 'error') console.log('console', m.text()); });
    await page.goto('http://localhost:8080/', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await new Promise((r) => setTimeout(r, 3500));
    await page.screenshot({ path: path.join(OUT, 'arc-0.png') });
    const box = await (await page.$('#babylon-canvas')).boundingBox();
    const cx = box.x + box.width / 2, cy = box.y + box.height / 2;
    // hover second button
    const paths = await page.$$('svg path[d^="M"]');
    console.log('paths', paths.length);
    if (paths[1]) {
      const b = await paths[1].boundingBox();
      await page.mouse.move(b.x + b.width / 2, b.y + b.height / 2);
      await new Promise((r) => setTimeout(r, 300));
      await page.screenshot({ path: path.join(OUT, 'arc-1-hover.png') });
    }
    await page.mouse.move(cx, cy);
    await page.mouse.down({ button: 'left' });
    await page.mouse.move(cx + 300, cy - 150, { steps: 20 });
    await page.mouse.up({ button: 'left' });
    await new Promise((r) => setTimeout(r, 1500));
    await page.screenshot({ path: path.join(OUT, 'arc-2-orbit.png') });
    for (let i = 0; i < 6; i++) { await page.mouse.wheel({ deltaY: 100 }); await new Promise((r) => setTimeout(r, 30)); }
    await new Promise((r) => setTimeout(r, 800));
    await page.screenshot({ path: path.join(OUT, 'arc-3-zoomout.png') });
  } finally { await browser.close(); }
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

