import React, { useEffect, useRef, useState } from 'react';
import { Upload, BoxSelect, LayoutGrid, Trash2, type LucideIcon } from 'lucide-react';

/**
 * Rangée de boutons courbe qui épouse le bord du plateau (mode Préparation). Toute la géométrie
 * est calculée par Viewport3D à partir de la projection du plateau et reçue par
 * `apex-plate-arc-layout` ; ce composant ne fait que dessiner et déclencher les actions.
 */
export interface PlateArcSegment {
  /** Contour SVG du bouton, en px CSS relatifs au canvas. */
  d: string;
  /** Centre du bouton (emplacement de l'icône). */
  cx: number;
  cy: number;
  /** Point d'ancrage de l'étiquette, juste à l'extérieur de la rangée. */
  lx: number;
  ly: number;
  /** Côté vers lequel l'étiquette s'étend depuis son ancrage. */
  labelSide: 'left' | 'right';
}

interface PlateAction {
  icon: LucideIcon;
  title: string;
  description: string;
  danger?: boolean;
}

/** L'ordre doit correspondre au nombre de segments produits par Viewport3D (PLATE_ARC_BUTTONS). */
const ACTIONS: PlateAction[] = [
  { icon: Upload, title: 'Importer un modèle', description: 'Ajoutez un fichier STL, GLB ou GLTF sur le plateau.' },
  { icon: BoxSelect, title: 'Tout sélectionner', description: 'Sélectionnez tous les modèles présents sur le plateau.' },
  { icon: LayoutGrid, title: 'Disposer automatiquement', description: 'Réorganisez les modèles au plus près du centre du plateau, sans chevauchement.' },
  { icon: Trash2, title: 'Tout supprimer', description: 'Retirez tous les modèles du plateau.', danger: true },
];

export const PlateActionArc: React.FC = () => {
  const [segments, setSegments] = useState<PlateArcSegment[] | null>(null);
  const [previewActive, setPreviewActive] = useState(false);
  const [hovered, setHovered] = useState<number | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const onLayout = (e: Event) => setSegments((e as CustomEvent<PlateArcSegment[] | null>).detail);
    const onPreview = (e: Event) => setPreviewActive(!!(e as CustomEvent<{ active: boolean }>).detail?.active);
    window.addEventListener('apex-plate-arc-layout', onLayout);
    window.addEventListener('apex-preview-toggled', onPreview);
    // La vue 3D ne republie la géométrie que lorsqu'elle change : on la redemande au montage
    // au cas où la première publication soit partie avant qu'on écoute.
    window.dispatchEvent(new CustomEvent('apex-request-plate-arc-layout'));
    return () => {
      window.removeEventListener('apex-plate-arc-layout', onLayout);
      window.removeEventListener('apex-preview-toggled', onPreview);
    };
  }, []);

  const runAction = (index: number) => {
    switch (index) {
      case 0: fileInputRef.current?.click(); break;
      case 1: window.dispatchEvent(new CustomEvent('apex-select-all-models')); break;
      case 2: window.dispatchEvent(new CustomEvent('apex-arrange-models')); break;
      case 3: window.dispatchEvent(new CustomEvent('apex-delete-all-models')); break;
    }
  };

  const setHover = (index: number | null) => {
    setHovered(index);
    if (index === null) {
      window.dispatchEvent(new CustomEvent('apex-reset-tooltip'));
    } else {
      const action = ACTIONS[index];
      window.dispatchEvent(new CustomEvent('apex-set-tooltip', { detail: { title: action.title, desc: action.description } }));
    }
  };

  const visible = !!segments && !previewActive;
  const hoveredSegment = visible && hovered !== null ? segments![hovered] : null;

  return (
    <>
      {visible && (
        <svg
          style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', zIndex: 15, pointerEvents: 'none', overflow: 'visible' }}
        >
          {segments!.map((seg, i) => {
            const action = ACTIONS[i];
            if (!action) return null;
            const isHovered = hovered === i;
            return (
              <path
                key={i}
                data-plate-arc-button={i}
                d={seg.d}
                onPointerEnter={() => setHover(i)}
                onPointerLeave={() => setHover(null)}
                onClick={() => runAction(i)}
                style={{
                  pointerEvents: 'auto',
                  cursor: 'pointer',
                  fill: isHovered
                    ? action.danger ? 'rgba(220,60,70,0.55)' : 'rgba(0,170,255,0.45)'
                    : 'rgba(20,22,30,0.6)',
                  stroke: isHovered ? 'rgba(255,255,255,0.45)' : 'rgba(255,255,255,0.18)',
                  strokeWidth: 1,
                  strokeLinejoin: 'round',
                  transition: 'fill 120ms ease, stroke 120ms ease',
                }}
              />
            );
          })}
        </svg>
      )}

      {visible && segments!.map((seg, i) => {
        const action = ACTIONS[i];
        if (!action) return null;
        const Icon = action.icon;
        return (
          <div
            key={i}
            style={{
              position: 'absolute', left: seg.cx, top: seg.cy, transform: 'translate(-50%, -50%)',
              zIndex: 16, pointerEvents: 'none', display: 'flex',
              color: hovered === i ? '#fff' : 'rgba(255,255,255,0.8)',
            }}
          >
            <Icon size={18} strokeWidth={1.8} />
          </div>
        );
      })}

      {hoveredSegment && (
        <div
          style={{
            position: 'absolute', left: hoveredSegment.lx, top: hoveredSegment.ly, zIndex: 17,
            transform: hoveredSegment.labelSide === 'left' ? 'translate(-100%, -50%)' : 'translate(0, -50%)',
            pointerEvents: 'none', background: 'rgba(20,22,30,0.85)', color: 'rgba(255,255,255,0.92)',
            fontSize: 12, padding: '5px 10px', borderRadius: 6, whiteSpace: 'nowrap',
            boxShadow: '0 4px 12px rgba(0,0,0,0.35)',
          }}
        >
          {ACTIONS[hovered!].title}
        </div>
      )}

      <input
        type="file"
        ref={fileInputRef}
        style={{ display: 'none' }}
        accept=".stl,.glb,.gltf"
        onChange={(e) => {
          if (e.target.files?.[0]) {
            window.dispatchEvent(new CustomEvent('apex-import-model', { detail: e.target.files[0] }));
          }
          e.target.value = '';
        }}
      />
    </>
  );
};

