// Placement : au plus près de l'angle souhaité, mais en faisant glisser la rangée le long
// du bord pour qu'elle reste entière dans le canvas et hors des panneaux d'interface.
if (--plateArcObstacleRefresh <= 0) {
  plateArcObstacleRefresh = 30;
  const canvasRect = canvas.getBoundingClientRect();
  plateArcObstacles = Array.from(document.querySelectorAll('[data-apex-chrome-panel]')).map((el) => {
    const r = el.getBoundingClientRect();
    return { l: r.left - canvasRect.left, t: r.top - canvasRect.top, r: r.right - canvasRect.left, b: r.bottom - canvasRect.top };
  }).filter((r) => r.r > r.l && r.b > r.t);
}
const cssW = canvas.clientWidth, cssH = canvas.clientHeight;
const outerOffset = PLATE_ARC_GAP_PX + PLATE_ARC_THICKNESS_PX;
const isFree = (x: number, y: number) =>
  x >= PLATE_ARC_MARGIN_PX && y >= PLATE_ARC_MARGIN_PX && x <= cssW - PLATE_ARC_MARGIN_PX && y <= cssH - PLATE_ARC_MARGIN_PX &&
  !plateArcObstacles.some((o) => x >= o.l - PLATE_ARC_MARGIN_PX && x <= o.r + PLATE_ARC_MARGIN_PX && y >= o.t - PLATE_ARC_MARGIN_PX && y <= o.b + PLATE_ARC_MARGIN_PX);
// Nombre cumulé d'échantillons bloqués (bord intérieur ou extérieur de la rangée hors zone).
const blockedPrefix = [0];
edge.forEach((p, i) => {
  const n = normals[i];
  const ok = isFree(p.x + n.x * PLATE_ARC_GAP_PX, p.y + n.y * PLATE_ARC_GAP_PX) && isFree(p.x + n.x * outerOffset, p.y + n.y * outerOffset);
  blockedPrefix.push(blockedPrefix[i] + (ok ? 0 : 1));
});
const desiredStart = arcLen[PLATE_ARC_CENTER_DEG - PLATE_ARC_SAMPLE_MIN_DEG] - rowLen / 2;
let start = Number.NaN;
let end = 0;
for (let i = 0; i < edge.length; i++) {
  while (end < edge.length - 1 && arcLen[end] < arcLen[i] + rowLen) end++;
  if (arcLen[end] < arcLen[i] + rowLen) break;
  // La rangée couvre les échantillons i..end (plus un demi-pas de chaque côté).
  const lo = Math.max(i - 1, 0), hi = Math.min(end + 1, edge.length - 1);
  if (blockedPrefix[hi + 1] - blockedPrefix[lo] > 0) continue;
  if (Number.isNaN(start) || Math.abs(arcLen[i] - desiredStart) < Math.abs(start - desiredStart)) start = arcLen[i];
}
if (Number.isNaN(start)) { publishPlateArc(null); return; }

